// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface ISavingsContractV2 {
    function underlying() external view returns (address);
    function exchangeRate() external view returns (uint256);
    function depositSavings(uint256 _amount) external returns (uint256 creditsIssued);
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(ISavingsContractV2(address(new __InvMutHandleStub()))); }

    function testFuzz_property(uint256 amount, address caller, address beneficiary) public {
        vm.assume(caller != address(0) && beneficiary != address(0));
        vm.assume(caller != beneficiary);
        vm.assume(caller != address(c));
        amount = bound(amount, 1, 1e24);

        uint256 before = c.imBalances(beneficiary);

        vm.prank(caller);
        try c.supplyTokenTo(amount, beneficiary) {
            // Rule: the beneficiary receives exactly the credits issued by the
            // savings deposit (stub issues `amount` credits); the caller gets none.
            assertTrue(c.imBalances(beneficiary) == before + amount && c.imBalances(caller) == 0);
        } catch {
            assertTrue(false);
        }
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external view returns (uint256) { return type(uint256).max; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function exchangeRate() external pure returns (uint256) { return 1e18; }
    function depositSavings(uint256 _amount) external returns (uint256) { return _amount; }
    function depositInterest(uint256) external pure {}
    receive() external payable {}
    fallback() external payable {}
}

